INSERT INTO `correos_enviados` VALUES (1,1,'informes@memoriasusbperu.com',NULL,'CotizaciÔö£Ôöén de Equipos','Cordial saludo\r\nAdjunto la cotizaciÔö£Ôöén\r\nEl equipo ofertado .\r\nResumen:\r\nEntrega: 4-10 dÔö£┬ías posteriores a orden de compra\r\nGarantÔö£┬ía: 1 aÔö£ÔûÆo\r\n podemos cotizar unidades adicionales o un modelo de mayor capacidad o menor capacidad si lo requiere.\r\n\r\nQuedo atento a cualquier consulta o ajuste necesario.\r\n\r\nSaludos cordiales, \r\nClifton Cabello Albino Internacional Company Peru SCRL Cel: +51 949296155 informes@cafe-peruano.com',1,NULL,'2026-07-10 14:01:13','2026-07-10 14:01:13'),(2,1,'informes@memoriasusbperu.com',NULL,'CotizaciÔö£Ôöén de Equipos','Cordial saludo\r\nAdjunto la cotizaciÔö£Ôöén\r\nEl equipo ofertado .\r\nResumen:\r\nEntrega: 4-10 dÔö£┬ías posteriores a orden de compra\r\nGarantÔö£┬ía: 1 aÔö£ÔûÆo\r\n podemos cotizar unidades adicionales o un modelo de mayor capacidad o menor capacidad si lo requiere.\r\n\r\nQuedo atento a cualquier consulta o ajuste necesario.\r\n\r\nSaludos cordiales, \r\nClifton Cabello Albino Internacional Company Peru SCRL Cel: +51 949296155 informes@cafe-peruano.com',1,NULL,'2026-07-10 14:20:23','2026-07-10 14:20:23');
