INSERT INTO `exim_incoterms` VALUES (1,'EXW','Ex Works','El vendedor entrega la mercancÔö£┬ía en sus instalaciones. El comprador asume todos los costos y riesgos desde la recogida.',0,0,0,0,0,0,NULL,NULL),(2,'FCA','Free Carrier','El vendedor entrega la mercancÔö£┬ía al transportista designado por el comprador en el lugar acordado.',1,0,0,1,0,0,NULL,NULL),(3,'FOB','Free On Board','El vendedor entrega la mercancÔö£┬ía a bordo del buque designado por el comprador en el puerto de origen.',1,0,0,1,0,0,NULL,NULL),(4,'CFR','Cost and Freight','El vendedor cubre el costo y el flete hasta el puerto de destino. El riesgo se transfiere al comprador cuando la mercancÔö£┬ía estÔö£├¡ a bordo.',1,1,0,1,0,0,NULL,NULL),(5,'CIF','Cost, Insurance and Freight','El vendedor cubre costo, flete y seguro hasta el puerto de destino. El riesgo se transfiere al comprador cuando estÔö£├¡ a bordo.',1,1,1,1,0,0,NULL,NULL),(6,'DAP','Delivered at Place','El vendedor entrega la mercancÔö£┬ía en el lugar acordado del paÔö£┬ís de destino. El comprador asume los costos de importaciÔö£Ôöén.',1,1,1,1,0,1,NULL,NULL),(7,'DDP','Delivered Duty Paid','El vendedor asume todos los costos y riesgos hasta entregar la mercancÔö£┬ía en el destino final, incluyendo aranceles de importaciÔö£Ôöén.',1,1,1,1,1,1,NULL,NULL);
