INSERT INTO `posts` VALUES (1,'Cafe Mono Tingales','cafe-mono-tingales-1','pr1',NULL,1,'2026-01-29 16:00:41','2026-01-30 02:14:20'),(2,'Cafe Mono Tingales','cafe-mono-tingales-2',NULL,NULL,1,'2026-01-29 16:12:07','2026-01-29 16:12:07'),(3,'Cafe Mono Tingales','cafe-mono-tingales-3','popopop',NULL,1,'2026-01-29 16:19:34','2026-01-31 04:56:38'),(4,'Tostados de cafe',NULL,'Caf?? tueste claro o ligero: acidez pronunciada, taza limpia, predominan sabores del origen.\r\nCaf?? tueste medio: balance entre acidez, dulzor y aromas.\r\nCaf?? tueste medio-oscuro: acidez baja, notas a chocolate, mayor textura que los anteriores caf??s.\r\nCaf?? tueste oscuro: notas a chocolate oscuro, mucha textura.',NULL,1,'2026-01-31 06:47:48','2026-01-31 06:50:47'),(5,'Tipos de Tostado Cafe',NULL,NULL,NULL,1,'2026-01-31 07:07:34','2026-01-31 07:07:34'),(6,'Tipos de Tostado en el Cafe','tipos-tostado-cafe-mono-tingales','Caf?? tueste claro o ligero: acidez pronunciada, taza limpia, predominan sabores del origen.\r\nCaf?? tueste medio: balance entre acidez, dulzor y aromas.\r\nCaf?? tueste medio-oscuro: acidez baja, notas a chocolate, mayor textura que los anteriores caf??s.\r\nCaf?? tueste oscuro: notas a chocolate oscuro, mucha textura.',NULL,1,'2026-01-31 07:10:00','2026-01-31 07:10:00'),(7,'Cafe Mono Tingales prueba',NULL,'Tingales prueba',NULL,1,'2026-02-01 04:45:08','2026-02-01 04:45:08'),(8,'Ôö¼ÔöÉCaf├® en grano o molido?','cafe-en-grano-o-molido','├ö├┐├▓ Ôö¼ÔöÉCafÔö£┬« en grano o molido? Esta es la pregunta.\r\n\r\n├ö┬ú├á GRANO ├ö├Ñ├å Dura mÔö£├¡s fresco, lo mueles justo al preparar, aroma mÔö£├¡s intenso.\r\n├ö┬ú├á MOLIDO ├ö├Ñ├å PrÔö£├¡ctico, listo, ideal para la maÔö£ÔûÆana rÔö£├¡pida.\r\n\r\nAmbos son 100% orgÔö£├¡nicos, tostados artesanalmente en Tingo MarÔö£┬ía.\r\n\r\nTÔö£Ôòæ Ôö¼ÔöÉcuÔö£├¡l prefieres? Te leemos ┬¡ãÆ├ª├º\r\n\r\n#monotingales #cafeperuano #cafegrano #cafemolido',NULL,1,'2026-06-28 00:28:22','2026-06-28 00:28:22');
/*!40000 ALTER TABLE `posts` ENABLE KEYS */;
